// skill-repo-readmes-private.mjs — regenerate the category READMEs and the top-level Categories
// table of a `sidekicks-skills-private`-shaped destination repo, from its own catalog.yaml (name,
// version, group, category) and each carried skill's SKILL.md frontmatter (description). Run right
// after the real `sidekicks skill export`. Its generated bytes ARE committed to the destination repo,
// so this script is tracked here rather than left as scratch tooling.
//
// It also writes the repo's prerequisites block into every category README and the top-level one, in
// its own generated region so a later regeneration rewrites it instead of dropping it.
//
// NORMALISED ONTO THE PUBLIC GENERATOR (2026-08-17). This script and skill-repo-readmes-public.mjs
// had drifted into answering the same questions differently, which is what two near-copies of one
// generator do. Four differences are gone:
//
//   - The generated region wrapped a separate `## Ungrouped` heading rather than the `## Categories`
//     table, so the two repos' marked regions were in different places.
//   - The family table was hand-maintained prose with two literal counts regex-patched into it
//     (`{database: 5, ops: 1}`), leaving every other family permanently reading 0.
//   - A missing `categories/<family>/README.md` threw ENOENT here and merely printed `skip:` there —
//     so `categories/framework/README.md`, absent from both published repos, killed only this run.
//   - Row counts, populated families, ungrouped counts and the unpublished-sibling list were literals
//     transcribed from the 2026-08-13 export. They made the script exit 1 against any other content,
//     including a freshly scaffolded repo, and made its published prose a frozen 2026-08-13 claim.
//
// Everything is derived now. What stays private is the PROSE — the install-order paragraph, the
// meta/export-notes.md pointer, and the proprietary framing — never the structure.
//
// RE-RUNNABLE. Every mutation is an upsert: create the structure if absent, otherwise rewrite
// strictly between markers. Idempotent against an already-generated destination.
//
// Usage (either form; `--dest` is the shared convention across this skill's generators):
//   node .agents/skills/sk-skill-manager/scripts/skill-repo-readmes-private.mjs <dest-src-root>
//   node .agents/skills/sk-skill-manager/scripts/skill-repo-readmes-private.mjs --dest <dest-src-root>
//
// Reads:
//   <dest>/catalog.yaml
//   <dest>/{.agents/skills,.sidekicks/skill-offloaded,.sidekicks/skills}/<name>/SKILL.md
//     — probed in that order, so a layout-3 destination (one tree) and a pre-bump layout-2/1 clone
//       all regenerate
// Writes:
//   <dest>/categories/<family>/README.md   (every family categories.yaml declares)
//   <dest>/README.md                       (Categories table + ungrouped rows + prerequisites)
//
// Marked-region contract (load-bearing — do not rename these strings):
//   <!-- GENERATED from catalog.yaml — do not hand-edit below this line. -->  /  <!-- END GENERATED -->
//   <!-- GENERATED prerequisites — do not hand-edit below this line. -->     /  <!-- END GENERATED prerequisites -->
// Zero third-party dependencies — node:fs / node:path only.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

function parseArgs(argv) {
  // Accept BOTH the original positional form (argv[0]) and `--dest <path>`, so existing callers
  // keep working unchanged while new callers can use the same convention as the other two
  // skill-repo generators in this directory.
  let dest = null;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--dest') { dest = argv[++i]; continue; }
    if (dest === null && !argv[i].startsWith('--')) dest = argv[i];
  }
  return dest;
}

const DEST = parseArgs(process.argv.slice(2));
if (!DEST) { console.error('usage: node private-readme-gen.mjs <dest-src-root> | --dest <dest-src-root>'); process.exit(1); }

function readCatalogRows(dest) {
  const text = readFileSync(join(dest, 'catalog.yaml'), 'utf8');
  const lines = text.split(/\r?\n/);
  const rows = [];
  let cur = null;
  for (const line of lines) {
    const nameMatch = line.match(/^\s*-\s*name:\s*'([^']*)'/);
    if (nameMatch) { if (cur) rows.push(cur); cur = { name: nameMatch[1] }; continue; }
    if (!cur) continue;
    const verMatch = line.match(/^\s*version:\s*'([^']*)'/);
    if (verMatch) cur.version = verMatch[1];
    const groupMatch = line.match(/^\s*group:\s*'([^']*)'/);
    if (groupMatch) cur.group = groupMatch[1];
    // The PUBLICATION family, distinct from the audit group above. Identical for every skill in the
    // private set today; read anyway so this generator and the public one group by the same field
    // and cannot answer the same question differently. An older catalog has no such column, which
    // is why the grouping below falls back to `group`.
    const categoryMatch = line.match(/^\s*category:\s*'([^']*)'/);
    if (categoryMatch) cur.category = categoryMatch[1];
  }
  if (cur) rows.push(cur);
  return rows;
}

// The trees a skills repository may hold, in probe order: layout 3 first — `.agents/skills` is the ONLY
// tree `skill export` writes today, for a parked source skill as much as an active one — with layout 2's
// parked tree and layout 1's single tree behind it as read tolerance, so a clone published before a bump
// still regenerates. Mirrors `DEST_TREES` in lib/skill-lifecycle/destinations.mjs, duplicated on purpose: a
// skill's script may not import from `lib/` or the folder stops being liftable.
//
// The WHOLE relative path per entry, never a basename to be re-joined onto a fixed prefix later.
// `.agents/skills` and `.sidekicks/skill-offloaded` do not share a parent, so a basename cannot say
// where a skill lives — and re-joining one reads EMPTY rather than failing. This function used to
// return `tree: 'skills'` for exactly that re-join, and the generated table links then pointed at a
// directory the destination does not have.
const DEST_TREES = ['.agents/skills', '.sidekicks/skill-offloaded', '.sidekicks/skills'];

function findSkillMd(dest, name) {
  for (const tree of DEST_TREES) {
    const dir = join(dest, ...tree.split('/'), name);
    const md = join(dir, 'SKILL.md');
    if (existsSync(md)) return { path: md, dir, tree };
  }
  return null;
}

function extractDescription(skillMdPath) {
  const text = readFileSync(skillMdPath, 'utf8');
  const lines = text.split(/\r?\n/);
  if (lines[0].trim() !== '---') return '';
  let end = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].trim() === '---') { end = i; break; }
  }
  if (end === -1) return '';
  const fm = lines.slice(1, end);
  const idx = fm.findIndex((l) => /^description:/.test(l));
  if (idx === -1) return '';
  const line = fm[idx];
  const rest = line.replace(/^description:\s*/, '');
  let raw = '';
  if (/^[>|][-+]?\s*$/.test(rest) || rest === '') {
    const baseIndent = (fm[idx].match(/^\s*/) || [''])[0].length;
    const parts = [];
    for (let j = idx + 1; j < fm.length; j++) {
      const l = fm[j];
      if (l.trim() === '') { parts.push(''); continue; }
      const indent = (l.match(/^\s*/) || [''])[0].length;
      if (indent <= baseIndent) break;
      parts.push(l.trim());
    }
    raw = parts.join(' ');
  } else {
    raw = rest;
  }
  raw = raw.trim().replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
  raw = raw.replace(/\s+/g, ' ').trim();
  return raw;
}

function truncate(s, max) {
  if (s.length <= max) return s;
  const cut = s.slice(0, max);
  const lastPeriod = cut.lastIndexOf('. ');
  if (lastPeriod > max * 0.4) return cut.slice(0, lastPeriod + 1);
  return cut.replace(/\s+\S*$/, '') + '…';
}

// --- 1. Load and enrich whatever the catalog holds ---------------------------------------
//
// The row count is not asserted. It used to demand exactly 24 — one export's measurement frozen as an
// invariant, so publishing or retracting a single skill made the generator exit 1 rather than
// regenerate. What IS worth refusing is an EMPTY catalog, matching the public generator: regenerating
// against zero rows would blank every table and read as "nothing is published here", which is
// indistinguishable from the truth only when it happens to be true.
const rows = readCatalogRows(DEST);
if (!rows.length) {
  console.error('FAIL: catalog.yaml carries zero rows — refusing to regenerate READMEs against an empty catalog (run the real export first)');
  process.exit(1);
}

const byGroup = new Map();
const ungrouped = [];
for (const r of rows) {
  const found = findSkillMd(DEST, r.name);
  if (!found) { console.error(`FAIL: no SKILL.md found for ${r.name} under ${DEST_TREES.join('/ or ')}/`); process.exit(1); }
  r.tree = found.tree;
  r.dir = found.dir;
  r.description = truncate(extractDescription(found.path) || '(no description found)', 160);
  // Measured, not assumed: no skill.manifest.yaml means no bundle{} baseline travelled with it.
  r.hasManifest = existsSync(join(found.dir, 'skill.manifest.yaml'));
  const family = r.category || r.group || '';
  if (family) {
    if (!byGroup.has(family)) byGroup.set(family, []);
    byGroup.get(family).push(r);
  } else {
    ungrouped.push(r);
  }
}

// --- 2. Nothing to sanity-check: every number is derived ------------------------------
//
// This used to assert `{database: 5, ops: 1}`, refuse any other populated family outright, and demand
// exactly 18 ungrouped skills. Those were one export's measurements frozen as invariants, so the
// script could only ever run against the 2026-08-13 destination: publishing a sixth database skill
// made it exit 1, and it could not run at all against a repo scaffolded fresh. The counts now come
// from `catalog.yaml` the way the public generator's do, which is what makes a re-export reproducible
// instead of requiring this file to be edited alongside it.

// `depth` is the caller's distance from the repo root, because this same table is written into
// `categories/<family>/README.md` (two levels down) AND into the root README. A single relative
// prefix is wrong in one of them, and a link that 404s in half the pages it appears on is worse than
// no link — this used to hardcode `../../`, so every row in the root README pointed two directories
// above the repository.
function tableFor(list, depth = 2) {
  const up = '../'.repeat(depth);
  const sorted = [...list].sort((a, b) => (a.name < b.name ? -1 : 1));
  const body = sorted
    .map((r) => `| [${r.name}](${up}${r.tree}/${r.name}/) | ${r.version} | ${r.description} |`)
    .join('\n');
  return `| Skill | Version | Description |\n|---|---|---|\n${body}`;
}

// --- 3. Category READMEs: a table for every populated family, prerequisites for all of them ----
const START = '<!-- GENERATED from catalog.yaml — do not hand-edit below this line. -->';
const END = '<!-- END GENERATED -->';

// A SECOND, independently-named region for the prerequisites block. Deliberately distinct markers
// rather than reusing START/END: a README now holds two regions and both are located with indexOf,
// so neither pair may be a substring of the other. ('<!-- END GENERATED prerequisites -->' does not
// contain '<!-- END GENERATED -->' — the trailing word sits before the closing `-->`.)
const PRE_START = '<!-- GENERATED prerequisites — do not hand-edit below this line. -->';
const PRE_END = '<!-- END GENERATED prerequisites -->';

// The families, read from this skill's own assets/categories.yaml — the single source both this
// generator and the public one use, so the two repos cannot end up with different family sets. It
// was a literal list here and a second literal in skill-repo-readmes-public.mjs until then.
//
// Family order matches the public generator: `framework` first, the rest alphabetical.
const CATEGORIES_YAML = join(
  dirname(dirname(fileURLToPath(import.meta.url))), 'assets', 'categories.yaml',
);
// BLURBS too, not just names: the top-level Categories table needs the "what it covers" column, and
// it used to be hand-authored prose in the destination README that this script patched counts into.
// Reading it from the same one source is what stops the two repos' tables from describing a family
// differently.
const { FAMILIES, BLURBS } = (() => {
  const names = [];
  const blurbs = new Map();
  let current = null;
  for (const raw of readFileSync(CATEGORIES_YAML, 'utf8').replace(/\r\n?/g, '\n').split('\n')) {
    const line = raw.replace(/\s+$/, '');
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const header = line.match(/^([a-z][a-z0-9-]*):\s*$/);
    if (header) { current = header[1]; names.push(current); continue; }
    const blurb = line.match(/^\s+blurb:\s+'(.*)'\s*$/);
    if (blurb && current) blurbs.set(current, blurb[1].replace(/''/g, "'"));
  }
  if (!names.length) { console.error(`FAIL: no families found in ${CATEGORIES_YAML}`); process.exit(1); }
  const missing = names.filter((f) => !blurbs.get(f));
  if (missing.length) {
    console.error(`FAIL: categories.yaml family without a blurb: ${missing.join(', ')} — the READMEs have nothing to say about it`);
    process.exit(1);
  }
  return {
    FAMILIES: [
      ...names.filter((f) => f === 'framework'),
      ...names.filter((f) => f !== 'framework').sort(),
    ],
    BLURBS: blurbs,
  };
})();

// Which siblings the published skills declare but this repo does not carry — MEASURED, from the
// manifests that actually travelled, exactly as the public generator measures it.
//
// This was two literal lists transcribed from one export report, which meant the generated prose
// stated a 2026-08-13 fact forever: a skill gaining or losing a sibling silently made it wrong, and
// nothing could notice. It also asserted WHERE each absent sibling lives (public repo vs framework
// core), which this script cannot know — a sibling is absent for several possible reasons, and naming
// the wrong source is worse than naming none. It now names the absences and points at the notes file.
function declaredSiblings(skillDir) {
  const abs = join(skillDir, 'skill.manifest.yaml');
  if (!existsSync(abs)) return [];
  const out = [];
  let inSiblings = false;
  for (const raw of readFileSync(abs, 'utf8').replace(/\r\n?/g, '\n').split('\n')) {
    const line = raw.replace(/\s+$/, '');
    if (!line.trim() || line.trim().startsWith('#')) continue;
    if (/^\s{2}sibling_skills:\s*$/.test(line)) { inSiblings = true; continue; }
    if (inSiblings && (/^\s{2}[a-z_]+:/.test(line) || /^\S/.test(line))) inSiblings = false;
    if (!inSiblings) continue;
    const m = line.match(/^\s+-?\s*skill:\s+(.+)$/);
    if (m) out.push(m[1].trim().replace(/^['"]|['"]$/g, ''));
  }
  return out;
}

const UNPUBLISHED_SIBLINGS = (() => {
  const have = new Set(rows.map((r) => r.name));
  const missing = new Set();
  for (const r of rows) {
    for (const sib of declaredSiblings(r.dir)) if (!have.has(sib)) missing.add(sib);
  }
  return [...missing].sort();
})();

const noBaseline = rows.filter((r) => !r.hasManifest).length;

// Prerequisites body. Numbers are DERIVED at run time (row count, manifest-less count), never
// hard-coded. `listNames` is passed only for the top-level README — repeating ten names in each of
// twelve category pages would be noise, so those point at meta/export-notes.md instead.
// The no-baseline fact is framework behaviour, not a defect of this export:
// lib/skill-lifecycle/manifest.mjs skips a skill that declares no dependency ("a skill that needs
// nothing gets nothing"), so no skill.manifest.yaml and therefore no bundle{} baseline is written;
// lib/skill-lifecycle/import.mjs then classifies such a copy `unversioned`, which is in its
// NEEDS_FORCE set. Accepted under AAP-115 (references/manifest-backfill.md).
function prerequisitesBody({ notesHref, listNames }) {
  const lines = [
    'Install in this order — **the [Sidekicks framework',
    'core](https://github.com/utranand/sidekicks-harness) first, then the public',
    '[sidekicks-skills](https://github.com/utranand/sidekicks-skills) repo, then this one** — so that a',
    'sibling a later layer declares is already present.',
    '',
  ];
  const n = UNPUBLISHED_SIBLINGS.length;
  if (!n) {
    lines.push('Every sibling skill declared by anything published here is also published here.');
  } else if (listNames) {
    lines.push(
      `Skills here declare ${n} sibling${n === 1 ? '' : 's'} not published in this repo:`,
      `${UNPUBLISHED_SIBLINGS.map((x) => `\`${x}\``).join(', ')}.`,
      `Each lives in the public repo, ships inside the framework core, or is vendored work nobody may`,
      `republish — [meta/export-notes.md](${notesHref}) records which.`,
    );
  } else {
    lines.push(
      `Skills here declare ${n} sibling${n === 1 ? '' : 's'} not published in this repo; each is named`,
      `in [meta/export-notes.md](${notesHref}) with what its absence costs.`,
    );
  }
  lines.push(
    '',
    `**Dependency-free skills carry no bundle baseline.** ${noBaseline} of the ${rows.length} skills published here`,
    'declare no Python import, node package, binary, framework file or sibling skill, so the framework',
    'writes them no `skill.manifest.yaml` and they export with no bundle baseline — `sidekicks skill',
    'import` reports them `unversioned` rather than verified, and needs `--force` to land one. That is',
    'framework design, accepted under AAP-115, not a packaging defect: the copy is still',
    'byte-identical and its provenance still travels in `meta/<name>/origin.yaml`.',
  );
  return lines.join('\n');
}

// Rewrite strictly between an existing marker pair.
function replaceRegion(text, startMarker, endMarker, body, where) {
  const s = text.indexOf(startMarker);
  const e = text.indexOf(endMarker);
  if (s === -1 || e === -1 || e < s) { console.error(`FAIL: ${startMarker} / ${endMarker} not found in ${where}`); process.exit(1); }
  return `${text.slice(0, s + startMarker.length)}\n\n${body}\n\n${text.slice(e)}`;
}

// Insert a `## Prerequisites` section carrying its own marker pair immediately before `anchor`
// (once, if absent), then always rewrite strictly between those markers.
function upsertPrerequisites(text, body, anchor, where) {
  let out = text;
  if (!out.includes(PRE_START)) {
    const idx = out.indexOf(`\n${anchor}`);
    if (idx === -1) { console.error(`FAIL: no "${anchor}" heading in ${where} to anchor the Prerequisites section before`); process.exit(1); }
    const at = idx + 1; // start of the anchor heading's own line
    out = `${out.slice(0, at)}## Prerequisites\n\n${PRE_START}\n${PRE_END}\n\n${out.slice(at)}`;
  }
  return replaceRegion(out, PRE_START, PRE_END, body, where);
}

const catPrereq = prerequisitesBody({ notesHref: '../../meta/export-notes.md', listNames: false });

let skipped = 0;
for (const family of FAMILIES) {
  const p = join(DEST, 'categories', family, 'README.md');
  const where = `categories/${family}/README.md`;
  // SKIP a family whose README does not exist, exactly as the public generator does. This used to
  // throw ENOENT here, which meant `categories/framework/README.md` -- absent from both published
  // repos -- killed the run outright while the public generator merely printed `skip:`. Two
  // generators over one family list must not disagree about what a missing page means.
  // `sidekicks skill repo init` scaffolds all of them, so a skip is now a signal, not the norm.
  if (!existsSync(p)) { console.error(`skip: ${where} does not exist`); skipped++; continue; }
  let text = readFileSync(p, 'utf8');
  const list = byGroup.get(family);
  if (list) {
    // Populated family — regenerate its table.
    text = replaceRegion(text, START, END, tableFor(list), where);
  } else if (!text.includes('_No skills published in this family yet._')) {
    // Empty family — its scaffold text is the correct content and must survive untouched.
    console.error(`FAIL: ${where} is an empty family but carries no "_No skills published in this family yet._" text`);
    process.exit(1);
  }
  text = upsertPrerequisites(text, catPrereq, '## Notes', where);
  writeFileSync(p, text, 'utf8');
  console.log(`updated ${where} — ${list ? `${list.length} skill(s)` : 'empty family (table text preserved)'} + prerequisites`);
}

// --- 4. Top-level README.md: one generated Categories table -------------------------------
//
// NORMALISED ONTO THE PUBLIC TOPOLOGY. Three things used to happen here instead, and each was a
// place the two repos could drift:
//
//   1. The family table was hand-maintained prose, and this script regex-patched two literal counts
//      (`{database: 5, ops: 1}`) into it. Any other family stayed permanently wrong at 0.
//   2. The generated region wrapped a separate `## Ungrouped` heading rather than the Categories
//      table, so the private README's marked region was somewhere else entirely from the public one.
//   3. Reaching that section meant matching a scaffold placeholder paragraph and destroying it, with
//      a hard FAIL if neither the placeholder nor its replacement was present.
//
// Now the region wraps `## Categories`, holds the whole derived table, and the ungrouped rows follow
// it in the same region — the public generator's shape exactly.
const readmePath = join(DEST, 'README.md');
let readme = readFileSync(readmePath, 'utf8');

const topBody = (() => {
  const out = ['| Family | What it covers | Skills |', '|---|---|---|'];
  for (const family of FAMILIES) {
    const count = (byGroup.get(family) || []).length;
    out.push(`| [${family}](categories/${family}/) | ${BLURBS.get(family) || ''} | ${count} |`);
  }
  out.push('');
  if (ungrouped.length) {
    out.push(
      'Ungrouped skills carry `category: \'\'` in `catalog.yaml` and are listed here rather than under a '
      + 'category:',
      '',
      tableFor(ungrouped, 0),
    );
  } else {
    out.push(
      'Ungrouped skills carry `category: \'\'` in `catalog.yaml` and are listed here rather than under a '
      + 'category. There are none yet.',
    );
  }
  return out.join('\n');
})();

readme = replaceRegion(readme, START, END, topBody, 'README.md');

// The prerequisites section goes AFTER the Ungrouped section and before `## Installing`, which is
// where a reader meets it just before the install commands it governs.
readme = upsertPrerequisites(
  readme,
  prerequisitesBody({ notesHref: 'meta/export-notes.md', listNames: true }),
  '## Installing',
  'README.md',
);

writeFileSync(readmePath, readme, 'utf8');
const populated = FAMILIES.filter((f) => (byGroup.get(f) || []).length).length;
console.log(`updated README.md — ${FAMILIES.length} family rows (${populated} populated), ${ungrouped.length} ungrouped, prerequisites`);
if (skipped) console.log(`${skipped} family README(s) skipped because they do not exist — 'sidekicks skill repo init' scaffolds them`);
console.log(`OK: every number derived from catalog.yaml and the manifests that travelled — ${rows.length} skill(s), ${noBaseline} without a bundle baseline, ${UNPUBLISHED_SIBLINGS.length} unpublished sibling(s)`);
